.art-sky{position:absolute;inset:0;background:radial-gradient(ellipse at 68% 55%,rgba(255,220,160,.28),transparent 45%)}
.art-sea{position:absolute;left:0;right:0;bottom:0;height:44%;background:linear-gradient(180deg,#c8835d,#7a4e52 42%,#1c3340);opacity:.9}
.art-sea:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(180deg,transparent 0 4px,rgba(255,255,255,.13) 4px 5px);mask-image:linear-gradient(180deg,transparent,#000)}
.art-city{position:absolute;left:0;right:0;bottom:42%;height:22%;background:
  linear-gradient(90deg,transparent 0 4%,#17323b 4% 8%,transparent 8% 11%,#1b3b44 11% 16%,transparent 16% 20%,#122c35 20% 26%,transparent 26% 30%,#183842 30% 36%,transparent 36% 43%,#0f2931 43% 52%,transparent 52% 58%,#183a44 58% 66%,transparent 66% 73%,#122c35 73% 80%,transparent 80% 88%,#1a3b45 88% 94%,transparent 94%);
  opacity:.8;clip-path:polygon(0 100%,0 62%,3% 62%,3% 30%,6% 30%,6% 70%,9% 70%,9% 18%,12% 18%,12% 55%,15% 55%,15% 35%,18% 35%,18% 78%,22% 78%,22% 45%,26% 45%,26% 25%,29% 25%,29% 60%,33% 60%,33% 40%,37% 40%,37% 70%,41% 70%,41% 15%,45% 15%,45% 52%,49% 52%,49% 32%,53% 32%,53% 64%,57% 64%,57% 44%,61% 44%,61% 22%,65% 22%,65% 58%,69% 58%,69% 38%,73% 38%,73% 68%,77% 68%,77% 48%,81% 48%,81% 28%,85% 28%,85% 60%,89% 60%,89% 42%,93% 42%,93% 72%,100% 72%,100% 100%)}
.art-palms{position:absolute;bottom:28%;left:0;right:0;height:55%}
.art-palms i{position:absolute;bottom:0;width:3px;height:52%;background:linear-gradient(180deg,#0b1f24,#123039);border-radius:3px;transform-origin:bottom;box-shadow:0 0 12px rgba(0,0,0,.3)}
.art-palms i:before,.art-palms i:after{content:"";position:absolute;top:-3px;left:50%;width:46px;height:16px;border-radius:100% 0 100% 0;border-top:3px solid #0b2025;transform:translateX(-50%) rotate(-18deg);transform-origin:left center}
