.vital span{font-size:6.5px;font-weight:800;color:#c4d2d4;width:15px;text-align:right}
.vital.stamina{opacity:.75}

.compass{position:absolute;top:16px;left:50%;transform:translateX(-50%);width:min(360px,30vw);height:30px;overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 18%,#000 82%,transparent);opacity:.9}
.compass-strip{position:absolute;left:50%;top:7px;display:flex;align-items:center;gap:15px;transform:translateX(-50%);font-size:8px;font-weight:800;letter-spacing:.12em;color:#dce7e8;white-space:nowrap;transition:transform .08s linear}
.compass-strip i{width:1px;height:5px;background:rgba(255,255,255,.35)}
