.char-meta{display:flex;flex-direction:column;gap:1px;min-width:105px}
.char-meta small{font-size:5.5px;letter-spacing:.22em;color:#7e9498;font-weight:800}
.char-meta b{font-family:var(--font-display);font-size:16px;letter-spacing:.05em;line-height:1}
.char-meta span{font-size:6px;letter-spacing:.16em;color:var(--gold);font-weight:800}
.char-switch{display:flex;flex-direction:column;align-items:center;gap:2px;border-left:1px solid rgba(255,255,255,.12);padding-left:8px}
.char-switch small{font-size:5px;letter-spacing:.12em;color:#7f9498;font-weight:700}
.hud-hints{display:flex;gap:8px;flex-wrap:wrap;font-size:7px;color:#b3c3c5;font-weight:600;text-shadow:0 1px 4px #000}
.hud-hints span{display:flex;align-items:center;gap:3px}
.hud-hints kbd{height:16px;font-size:8px;min-width:16px}

.hud-bottom-right{position:absolute;bottom:20px;right:20px;display:flex;flex-direction:column;align-items:flex-end;gap:7px;transform-origin:bottom right;transform:scale(var(--hud-scale))}
.weapon-card{position:relative;display:flex;align-items:center;gap:10px;padding:8px 14px 8px 10px;background:linear-gradient(90deg,rgba(5,14,19,.55),rgba(5,14,19,.92));border:1px solid rgba(255,255,255,.13);border-radius:7px;backdrop-filter:blur(7px);overflow:hidden;min-width:218px}
.weapon-ico{width:30px;height:30px;display:grid;place-items:center;background:rgba(255,196,107,.12);border:1px solid rgba(255,196,107,.3);border-radius:4px;color:var(--gold);font-size:11px}
