World.prototype.nearestRoad = function (x, z) {
  let best = { x, z, axis: 'x', dist: Infinity };
  for (const rx of ROADS_X) {
    const d = Math.abs(x - rx);
    if (d < best.dist) best = { x: rx, z, axis: 'x', dist: d, road: rx };
