    $('chapter-time').textContent = def.time;
    $('chapter-sub').textContent = def.sub;
    el.classList.remove('hidden');
    this.cutscene = true;
    clearTimeout(this._chapterTO);
    this._chapterTO = setTimeout(() => {
      el.classList.add('hidden');
      this.cutscene = false;
      this._last = performance.now();
