import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const url = process.env.URL || 'http://127.0.0.1:4173/';
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });

const LOW = { quality: 'medium', resScale: 60, shadows: false, water: 'low', distance: 60, showFps: true };
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });

async function makePage(opts = {}, settings = LOW) {
  const page = await browser.newPage(opts);
  page.setDefaultTimeout(90000);
  await page.addInitScript((s) => {
    localStorage.setItem('matteo5.settings.v1', JSON.stringify(s));
    localStorage.removeItem('matteo5.save.v1');
  }, settings);
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible', timeout: 60000 });
  return page;
}

const page = await makePage({ viewport: { width: 1440, height: 900 } });
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/02-menu.png` });
console.log('menu ok');

await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/03-charselect.png` });
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(1800);
await page.locator('#tutorial:not(.hidden) #tut-start').click().catch(() => {});
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/04-game.png` });
console.log('state', await page.evaluate(() => {
  const g = window.__game;
  return { mode: g.mode, char: g.player?.charId, pos: { x: Math.round(g.player.pos.x), z: Math.round(g.player.pos.z) }, hud: !document.getElementById('hud').classList.contains('hidden'), fps: Math.round(g.fps), vehicles: g.vehicles.length };
}));

await page.keyboard.down('KeyW');
await page.waitForTimeout(900);
await page.keyboard.up('KeyW');
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/05-walk.png` });

await page.keyboard.press('KeyM');
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/06-map.png` });
console.log('map open', await page.locator('#map-overlay').isVisible());
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

await page.keyboard.press('Escape');
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/07-pause.png` });
console.log('pause rows', await page.locator('.pm-row').count());
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// Mission flow with teleports
await page.evaluate(() => window.__game.startMissionById('m1'));
await page.waitForTimeout(3200);
await page.screenshot({ path: `${out}/08-mission-intro.png` });
await page.evaluate(() => { const g = window.__game; g.player.pos.set(596, 0, 114); g._placePlayer(); g._snapCamera(); });
await page.waitForTimeout(1200);
console.log('dialog visible', await page.locator('#dialogue').isVisible());
await page.screenshot({ path: `${out}/09-dialogue.png` });
for (let i = 0; i < 4; i++) {
  if (await page.locator('#dialogue').isVisible()) await page.locator('#dlg-next').click();
  await page.waitForTimeout(350);
}
await page.waitForTimeout(900);
console.log('after dialog', await page.evaluate(() => { const g = window.__game; return { step: g.mission?.step, dialog: g.dialogueActive, target: !!g._targetCar, objective: document.getElementById('obj-text').textContent }; }));
await page.screenshot({ path: `${out}/10-chase.png` });

// capture target
await page.evaluate(() => { const g = window.__game; if (g._targetCar) { g.player.pos.set(g._targetCar.pos.x - 4, 0, g._targetCar.pos.z); g._placePlayer(); g._snapCamera(); } });
await page.waitForTimeout(1400);
for (let i = 0; i < 4; i++) {
  if (await page.locator('#dialogue').isVisible()) await page.locator('#dlg-next').click();
  await page.waitForTimeout(300);
}
await page.waitForTimeout(700);
console.log('after chase', await page.evaluate(() => ({ step: window.__game.mission?.step, objective: document.getElementById('obj-text').textContent })));
// go to pier
await page.evaluate(() => { const g = window.__game; g.player.pos.set(782, 0, 140); g._placePlayer(); g._snapCamera(); });
await page.waitForTimeout(1400);
for (let i = 0; i < 4; i++) {
  if (await page.locator('#dialogue').isVisible()) await page.locator('#dlg-next').click();
  await page.waitForTimeout(300);
}
await page.waitForTimeout(900);
console.log('result', await page.evaluate(() => ({ open: window.__game.resultOpen, completed: [...window.__game.completed], money: window.__game.player.money })));
await page.screenshot({ path: `${out}/11-result.png` });
await page.locator('#btn-result-next').click();
await page.waitForTimeout(500);

// RP modal + job
await page.keyboard.press('Escape');
await page.waitForTimeout(400);
await page.locator('[data-pause="rp"]').click();
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/12-rp.png` });
console.log('rp jobs', await page.locator('.rp-job').count());
await page.locator('.rp-job').first().click();
await page.waitForTimeout(900);
console.log('rp active', await page.evaluate(() => !!window.__game.rpJob));
await page.screenshot({ path: `${out}/13-rp-job.png` });

// settings
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
await page.locator('[data-pause="settings"]').click();
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/14-settings.png` });
await page.locator('[data-close="settings-modal"]').first().click();
await page.waitForTimeout(300);

// mobile
const mp = await makePage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 }, { ...LOW, resScale: 50 });
await mp.waitForTimeout(500);
await mp.screenshot({ path: `${out}/15-mobile-menu.png` });
await mp.locator('[data-menu="play"]').click();
await mp.waitForTimeout(400);
await mp.screenshot({ path: `${out}/16-mobile-char.png` });
await mp.locator('.cs-card.luiza').click();
await mp.waitForTimeout(1600);
await mp.locator('#tut-start').click().catch(() => {});
await mp.waitForTimeout(600);
await mp.screenshot({ path: `${out}/17-mobile-game.png` });
console.log('mobile', await mp.evaluate(() => ({ touch: document.body.classList.contains('touch-mode'), hud: !document.getElementById('hud').classList.contains('hidden'), touchVisible: !document.getElementById('touch-controls').classList.contains('hidden') })));

await browser.close();
console.log('DONE');

